import { Order } from "../domain/order";
import { OrderLine } from "../domain/order-line";
import { OrderRepository } from "../domain/order-repository";
import { ProductRepository } from "../domain/product-repository";
import { reserveStock } from "../domain/stock-reservation";
import { OrderDto, PlaceOrderCommand, toOrderDto } from "./order-dto";

export class PlaceOrderUseCase {
  constructor(
    private readonly orders: OrderRepository,
    private readonly products: ProductRepository,
  ) {}

  async execute(command: PlaceOrderCommand): Promise<OrderDto> {
    const lines = command.lines.map((line) => new OrderLine(line.productId, line.quantity));
    const order = new Order(this.orders.nextId(), lines);

    const found = await this.products.findByIds(lines.map((line) => line.productId));
    const byId = new Map(found.map((product) => [product.id, product]));
    reserveStock(byId, lines);

    for (const product of byId.values()) {
      await this.products.save(product);
    }
    await this.orders.save(order);
    return toOrderDto(order);
  }
}

